package com.autoops.execution.controller;import com.autoops.execution.service.ExecutionService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/executions")public class ExecutionStartController{private final ExecutionService service;public ExecutionStartController(ExecutionService s){service=s;}public record Start(Long commandId,List<ExecutionService.Target> targets,String resolvedCommand){}@PostMapping("/{id}/start")public void start(@PathVariable Long id,@RequestBody Start r){service.startResolvedCommand(id,r.commandId(),r.targets(),r.resolvedCommand());}}
